import Chart from "chart.js/auto";

interface Series {
  labels: string[];
  values: number[];
}

const charts = new WeakMap<HTMLCanvasElement, Chart<"bar", number[], string>>();

jaspring.hooks.register<HTMLCanvasElement, Series>("chart", {
  mounted(el, ctx) {
    const chart = new Chart(el, {
      type: "bar",
      data: {
        labels: ctx.params.labels,
        datasets: [{ label: "Sales", data: ctx.params.values }],
      },
      options: {
        maintainAspectRatio: false,
        onClick: (_, bars) => {
          if (bars.length) ctx.pushEvent("bar-picked", { index: bars[0].index });
        },
      },
    });
    charts.set(el, chart);
  },
  updated(el, ctx) {
    const chart = charts.get(el);
    if (!chart) return;
    chart.data.labels = ctx.params.labels;
    chart.data.datasets[0].data = ctx.params.values;
    chart.update();
  },
  destroyed(el) {
    charts.get(el)?.destroy();
    charts.delete(el);
  },
  total(el) {
    const values = charts.get(el)?.data.datasets[0].data ?? [];
    return values.reduce((sum, value) => sum + value, 0);
  },
});

